//! `pascrust_runtime` is the library that every Rust program generated by
//! pascrust depends on. It plays the role of Turbo Pascal's `System` unit
//! (plus `Crt`, `Dos` and `Graph`, behind Cargo features): it holds the
//! Pascal-flavoured types (`PString`, `PArray`, `Ptr`, ...) and the built-in
//! procedures (`Writeln`, `Length`, `Halt`, ...).
//!
//! Generated code starts with `use pascrust_runtime::prelude::*;`, so
//! everything a program normally needs is in scope.

pub mod array;
#[cfg(any(feature = "crt", feature = "graph"))]
pub mod colors;
pub mod cp437;
#[cfg(feature = "crt")]
pub mod crt;
#[cfg(feature = "dos")]
pub mod dos;
#[cfg(feature = "graph")]
pub mod graph;
pub mod io;
pub mod ordinal;
pub mod overlay;
pub mod prelude;
pub mod printer;
pub mod ptr;
pub mod run;
pub mod set;
pub mod string;
pub mod system;

pub use run::{RuntimeError, halt, rte, run};
